def most_frequent_two_gram(n, s):
    two_gram_counts = Counter(s[i:i+2] for i in range(n - 1))
    max_count = max(two_gram_counts.values())
    for two_gram, count in two_gram_counts.items():
        if count == max_count:
            return two_gram

